#!/usr/bin/env Rscript

library(rstan)

rstan_options(auto_write = TRUE)
options(mc.cores = 4)

observations <- read.csv("/app/data.csv", header = TRUE)
if (!all(c("y", "n") %in% names(observations))) {
  stop("/app/data.csv must contain columns named 'y' and 'n'")
}
if (anyNA(observations[, c("y", "n")])) {
  stop("The y and n columns must not contain missing values")
}
if (any(observations$y < 0 | observations$n < 0 | observations$y > observations$n)) {
  stop("The data must satisfy 0 <= y <= n")
}

stan_data <- list(
  N = nrow(observations),
  y = as.integer(observations$y),
  n = as.integer(observations$n)
)

model <- rstan::stan_model(file = "/app/hierarchical_model.stan")
fit <- rstan::sampling(
  object = model,
  data = stan_data,
  chains = 4,
  iter = 100000,
  warmup = 50000,
  seed = 1,
  cores = 4,
  control = list(adapt_delta = 0.95),
  refresh = 1000
)

posterior <- rstan::extract(fit, pars = c("alpha", "beta"), permuted = TRUE)
alpha_mean <- mean(posterior$alpha)
beta_mean <- mean(posterior$beta)

writeLines(sprintf("%.17g", alpha_mean), "/app/posterior_alpha_mean.txt")
writeLines(sprintf("%.17g", beta_mean), "/app/posterior_beta_mean.txt")

